package com.rescuefarm.ui.seller;
import androidx.lifecycle.*;import com.rescuefarm.data.repository.*;import com.rescuefarm.domain.model.*;import com.rescuefarm.service.seller.*;import java.util.*;
public class SellerViewModel extends ViewModel{private final String sellerId;private final ProductRepository productRepo;private final CampaignRepository campaignRepo;private final PostRepository postRepo;private final OrderRepository orderRepo;private final UserRepository userRepo;private final SellerDashboardAggregator aggregator=new SellerDashboardAggregator();private final MediatorLiveData<SellerDashboardState>state=new MediatorLiveData<>();private List<Product>products=new ArrayList<>();private List<RescueCampaign>campaigns=new ArrayList<>();private List<Post>posts=new ArrayList<>();private List<Order>orders=new ArrayList<>();private List<OrderItem>deliveredItems=new ArrayList<>();private int promotionCount,pending,pendingItemLoads,analyticsGeneration;private boolean approved,failed,analyticsReady,analyticsLoading;
 public SellerViewModel(String id,ProductRepository p,CampaignRepository c,PostRepository x,OrderRepository o,UserRepository u){sellerId=id;productRepo=p;campaignRepo=c;postRepo=x;orderRepo=o;userRepo=u;state.setValue(SellerDashboardState.of(SellerDashboardState.Status.VERIFYING,null,"Đang xác minh seller…"));state.addSource(p.observeSellerProducts(id),v->{products=safe(v);publish();});state.addSource(c.observeSellerCampaigns(id),v->{campaigns=safe(v);publish();});state.addSource(x.observeSellerPosts(id),v->{posts=safe(v);publish();});state.addSource(o.observeSellerOrders(id),v->{orders=safe(v);if(approved&&pending==0&&!failed)loadDeliveredItems();publish();});}
 public LiveData<SellerDashboardState>getState(){return state;}public void refresh(){if(sellerId==null||sellerId.trim().isEmpty()){state.setValue(SellerDashboardState.of(SellerDashboardState.Status.ERROR,null,"Cần đăng nhập seller."));return;}state.setValue(SellerDashboardState.of(SellerDashboardState.Status.VERIFYING,null,"Đang xác minh seller…"));userRepo.getUser(sellerId,new UserRepository.UserCallback(){public void onSuccess(User user){if(!(user instanceof Seller)||!((Seller)user).canSell()){approved=false;state.postValue(SellerDashboardState.of(SellerDashboardState.Status.NOT_APPROVED,null,"Seller phải được duyệt trước khi quản lý gian hàng."));return;}approved=true;loadAll();}public void onError(UserRepository.ProfileError e,String m){state.postValue(SellerDashboardState.of(SellerDashboardState.Status.ERROR,null,m));}});}
 private void loadAll(){pending=5;failed=false;analyticsReady=false;analyticsLoading=false;deliveredItems.clear();state.setValue(SellerDashboardState.of(SellerDashboardState.Status.LOADING,null,"Đang tải dashboard seller…"));productRepo.refreshSellerProducts(sellerId,new ProductRepository.ActionCallback(){public void onSuccess(){done();}public void onError(ProductRepository.ErrorCode e,String m){fail(m);}});productRepo.getSellerPromotions(sellerId,new ProductRepository.PromotionListCallback(){public void onSuccess(List<com.rescuefarm.domain.model.Promotion>x){promotionCount=x==null?0:x.size();done();}public void onError(ProductRepository.ErrorCode e,String m){fail(m);}});campaignRepo.refreshSellerCampaigns(sellerId,new CampaignRepository.ActionCallback(){public void onSuccess(){done();}public void onError(CampaignRepository.ErrorCode e,String m){fail(m);}});postRepo.refreshSellerPosts(sellerId,new PostRepository.ActionCallback(){public void onSuccess(){done();}public void onError(PostRepository.ErrorCode e,String m){fail(m);}});orderRepo.refreshSellerOrders(sellerId,new OrderRepository.ActionCallback(){public void onSuccess(){done();}public void onError(OrderRepository.ErrorCode e,String m){fail(m);}});}
 private synchronized void done(){if(pending>0)pending--;if(pending==0&&!analyticsLoading)loadDeliveredItems();publish();}private synchronized void fail(String m){failed=true;if(pending>0)pending--;state.postValue(SellerDashboardState.of(SellerDashboardState.Status.ERROR,null,m));}
 private synchronized void loadDeliveredItems(){if(analyticsLoading||pending>0)return;analyticsLoading=true;analyticsReady=false;final int generation=++analyticsGeneration;List<Order> completed=new ArrayList<>();for(Order order:orders)if(order.getStatus()==com.rescuefarm.domain.enums.OrderStatus.DELIVERED)completed.add(order);pendingItemLoads=completed.size();deliveredItems.clear();if(completed.isEmpty()){analyticsReady=true;analyticsLoading=false;publish();return;}for(Order order:completed)orderRepo.getOrderItems(order.getId(),new OrderRepository.ItemCallback(){public void success(List<OrderItem>items){synchronized(SellerViewModel.this){if(generation!=analyticsGeneration)return;if(items!=null)deliveredItems.addAll(items);finishItemLoad();}}public void error(String message){synchronized(SellerViewModel.this){if(generation!=analyticsGeneration)return;failed=true;analyticsLoading=false;state.postValue(SellerDashboardState.of(SellerDashboardState.Status.ERROR,null,"Không thể tải mặt hàng đơn đã giao để tính thống kê: "+message));}}});}
 private synchronized void finishItemLoad(){if(pendingItemLoads>0)pendingItemLoads--;if(pendingItemLoads==0){analyticsReady=true;analyticsLoading=false;publish();}}
 private void publish(){if(!approved||pending>0||failed||!analyticsReady)return;SellerDashboardSnapshot x=aggregator.aggregate(sellerId,products,campaigns,posts,orders,deliveredItems,promotionCount);state.postValue(SellerDashboardState.of(x.isEmpty()?SellerDashboardState.Status.EMPTY:SellerDashboardState.Status.READY,x,x.isEmpty()?"Chưa có dữ liệu seller.":"Đã đồng bộ dashboard."));}
 private static <T>List<T>safe(List<T>x){return x==null?new ArrayList<>():new ArrayList<>(x);}@Override protected void onCleared(){productRepo.close();campaignRepo.close();postRepo.close();orderRepo.close();}}
